// Register shader with UE5
IMPLEMENT_GLOBAL_SHADER(FK10FloraShader, "/Plugin/KainCosmos/Shaders/K10Flora.usf", "K10FloraCS", SF_Compute);

// Helper function to add pass to render graph
void AddPass_K10Flora(
    FRDGBuilder& GraphBuilder,
    FRDGTextureRef biome_map,
    FRDGTextureRef OutputTexture,
    FIntVector GroupCount
)
{
    FK10FloraShader::FParameters* Params = GraphBuilder.AllocParameters<FK10FloraShader::FParameters>();
    // Bind Textures
    Params->biome_map = biome_map;
    Params->biome_mapSampler = TStaticSamplerState<SF_Bilinear, AM_Clamp, AM_Clamp, AM_Clamp>::GetRHI();
    // Bind UAVs
    Params->OutputTexture = GraphBuilder.CreateUAV(OutputTexture);

    FK10FloraShader::Exec(GraphBuilder, *Params, GroupCount);
}
